def check(cases):
    for start, spec_text, is_dir, umask, expected in cases:
        got = apply_chmod(start, spec_text, is_dir, umask)
        assert got == expected, (
            f"apply_chmod({start:#06o}, {spec_text!r}, is_dir={is_dir}, umask={umask:#05o}) "
            f"gave {got:#06o}, expected {expected:#06o}"
        )


def raises(exc, fn, *args):
    try:
        fn(*args)
    except exc as e:
        return str(e)
    raise AssertionError(f"expected {exc.__name__} from {args!r}")


def test_cases_checked_against_real_gnu_chmod():
    check(ORACLE_CASES)


def test_only_the_low_twelve_bits_of_the_mode_are_used():
    assert apply_chmod(0o100644, "u+x") == 0o744
    assert apply_chmod(0o40755, "g-w", True) == 0o755
    assert apply_chmod(0o100000, "755") == 0o755
    assert apply_chmod(0o104755, "a=") == 0
    assert mode_string(0o100755) == "-rwxr-xr-x"
    assert mode_string(0o41777, True) == "drwxrwxrwt"


def test_negative_mode_is_a_value_error():
    raises(ValueError, apply_chmod, -1, "u+x")


def test_only_the_low_nine_bits_of_the_umask_are_used():
    assert apply_chmod(0o755, "+t", F, 0o1022) == 0o1755
    assert apply_chmod(0o644, "+x", F, 0o022 | 0o7000) == 0o755
    assert apply_chmod(0o644, "+x", F, 0o4027) == 0o754


def test_result_is_a_plain_int_in_range():
    for spec_text in ["777", "a+rwxst", "a=", "u=rwx,g=u,o=u"]:
        r = apply_chmod(0o644, spec_text)
        assert type(r) is int and 0 <= r <= 0o7777


def test_default_arguments_are_a_file_and_umask_022():
    assert apply_chmod(0o644, "a+X") == 0o644
    assert apply_chmod(0o444, "+w") == 0o644
    assert apply_chmod(0o755, "-w") == 0o555


def test_clauses_run_left_to_right_on_the_running_result():
    check([
        (0o700, "u=r,g=u", F, 0o022, 0o440),
        (0o750, "g=u,u=r", F, 0o022, 0o470),
        (0o000, "u=rwx,g=u,o=u", F, 0o022, 0o777),
        (0o600, "u+x,go+X", F, 0o022, 0o711),
        (0o755, "a=rx,u+w", F, 0o022, 0o755),
        (0o644, "a+r,u+w,go-w", F, 0o022, 0o644),
        (0o644, "a=rwx,a-x", F, 0o022, 0o666),
        (0o755, "u+rwx-w", F, 0o022, 0o555),
        (0o700, "g+u-w,o+g", F, 0o022, 0o755),
    ])


def test_empty_permissions_and_bare_operators_are_valid():
    check([
        (0o644, "u+", F, 0o022, 0o644),
        (0o644, "+", F, 0o022, 0o644),
        (0o644, "-", F, 0o022, 0o644),
        (0o644, "=", F, 0o022, 0o000),
        (0o755, "g=", F, 0o022, 0o705),
        (0o755, "ug-", F, 0o022, 0o755),
    ])


def test_who_letters_in_any_order_and_repeated():
    check([
        (0o600, "ou+r", F, 0o022, 0o604),
        (0o600, "gu+r", F, 0o022, 0o640),
        (0o600, "ggo+r", F, 0o022, 0o644),
        (0o600, "aa+r", F, 0o022, 0o644),
        (0o600, "ugoa-rw", F, 0o022, 0o000),
    ])


def test_repeated_permission_letters_are_harmless():
    check([(0o600, "g+rr", F, 0o022, 0o640), (0o600, "g+rwxrwx", F, 0o022, 0o670)])


def test_capital_x_without_who_and_with_the_umask():
    check([
        (0o640, "+X", D, 0o022, 0o751),
        (0o640, "+X", D, 0o001, 0o750),
        (0o640, "+X", F, 0o022, 0o640),
        (0o740, "+X", F, 0o022, 0o751),
        (0o001, "u+X,g+X", F, 0o022, 0o111),
        (0o444, "=rX", F, 0o022, 0o444),
        (0o444, "a=rX", D, 0o022, 0o555),
    ])


