def test_mode_string_special_bits_in_every_position():
    assert mode_string(0o6755) == "-rwsr-sr-x"
    assert mode_string(0o6644) == "-rwSr-Sr--"
    assert mode_string(0o1000, True) == "d--------T"
    assert mode_string(0o1001, True) == "d--------t"
    assert mode_string(0o7000) == "---S--S--T"
    assert mode_string(0o4100) == "-" + "--s" + "------"
    assert mode_string(0o2010) == "-" + "---" + "--s" + "---"
    assert mode_string(0o2000) == "-" + "---" + "--S" + "---"


def test_mode_string_every_permission_triple():
    letters = ["---", "--x", "-w-", "-wx", "r--", "r-x", "rw-", "rwx"]
    for u in range(8):
        for g in range(8):
            for o in range(8):
                expected = "-" + letters[u] + letters[g] + letters[o]
                assert mode_string((u << 6) | (g << 3) | o) == expected
                assert mode_string((u << 6) | (g << 3) | o, True) == "d" + expected[1:]


def test_more_invalid_specs():
    for bad in ["+440", "-755", "=755", "u=755", "7,u+x", "u+x,755", " u+x", "u+x ", "U+x", "u+X1", "0x1", "u+x;", ",", "u,g",
                "0789", "10000", "u+x,,g+w", "ug", "g=uu", "g=ug", "=u,", "u+rwxz", "a+X+q", "a~x", "100000"]:
        message = raises(ValueError, apply_chmod, 0o644, bad)
        assert repr(bad) in message, (bad, message)


def test_valid_unusual_specs_are_accepted():
    check([
        (0o644, "+-", F, 0o022, 0o644),
        (0o644, "a=r-r", F, 0o022, 0o000),
        (0o644, "g=u-w", F, 0o022, 0o644),
        (0o644, "u=rwx,go=u-w", F, 0o022, 0o755),
        (0o644, "00644", F, 0o022, 0o644),
        (0o644, "0000", F, 0o022, 0o000),
    ])


